### Iteration 2: Shared Memory Optimization
We'll implement a tiled matrix multiplication using shared memory. This approach loads blocks of matrices A and B into shared memory, reducing the number of global memory accesses.

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the optimized CUDA kernel with shared memory
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* a, const float* b, float* out, int N) {
    // Define tile size and shared memory
    const int TILE_SIZE = 16;
    __shared__ float tileA[TILE_SIZE][TILE_SIZE];
    __shared__ float tileB[TILE_SIZE][TILE_SIZE];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x * TILE_SIZE;
    int by = blockIdx.y * TILE_SIZE;

    int row = by + ty;
    int col = bx + tx;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < N; t += TILE_SIZE) {
        // Load tiles into shared memory
        if (row < N && (t + tx) < N) {
            tileA[ty][tx] = a[row * N + t + tx];
        } else {
            tileA[ty][tx] = 0.0f;
        }

        if ((t + ty) < N && col < N) {
            tileB[ty][tx] = b[(t + ty) * N + col];
        } else {
            tileB[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial product
        for (int k = 0; k < TILE_SIZE; k++) {
            sum += tileA[ty][k] * tileB[k][tx];
        }

        __syncthreads();
    }

    // Write result
    if (row < N && col < N) {
        out[row * N + col] = sum;
    }
}

