    TORCH_CHECK(a.device().is_cuda(), "a must be on CUDA");
    TORCH_CHECK(b.device().is_cuda(), "b must be on CUDA");

    int N = a.size(0);
    auto out = torch::zeros({N, N}, a.options());

    // Set block and grid dimensions
