import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define further optimized CUDA kernel
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 64
#define UNROLL_FACTOR 4
#define REG_TILE_SIZE 4

__global__ void matmul_kernel(const float* a, const float* b, float* out, int N) {
    // Define shared memory tiles
    __shared__ float tileA[TILE_SIZE][TILE_SIZE];
    __shared__ float tileB[TILE_SIZE][TILE_SIZE];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x * TILE_SIZE;
    int by = blockIdx.y * TILE_SIZE;

    int row = by + ty;
    int col = bx + tx;

    // Register accumulation
    float sum[REG_TILE_SIZE][REG_TILE_SIZE] = {{0}};

    // Loop over tiles
    for (int t = 0; t < N; t += TILE_SIZE) {
        // Load tiles into shared memory with coalesced access
        if (row < N && (t + tx) < N) {
            tileA[ty][tx] = a[row * N + t + tx];
        } else {
            tileA[ty][tx] = 0.0f;
        }

        if ((t + ty) < N && col < N) {
            tileB[ty][tx] = b[(t + ty) * N + col];
        } else {
            tileB[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial product with register tiling
        for (int k = 0; k < TILE_SIZE; k += REG_TILE_SIZE) {
            // Prefetch tile to registers
            float regA[REG_TILE_SIZE];
            float regB[REG_TILE_SIZE];

            #pragma unroll
            for (int i = 0; i < REG_TILE_SIZE; i++) {
                regA[i] = tileA[ty][k + i];
            }

            #pragma unroll
            for (int j = 0; j < REG_TILE_SIZE; j++) {
                regB[j] = tileB[k + j][tx];
            }

            // Compute dot products
            #pragma unroll
            for (int i = 0; i < REG_TILE_SIZE; i++) {
                #pragma unroll
                for (int j = 0; j < REG_TILE_SIZE; j++) {
                    sum[i][j] += regA[i] * regB[j];
                }
            }
        }

        __syncthreads();
    }

    // Write result
    if (row < N && col < N) {
        #pragma unroll
        for (int i = 0; i < REG_TILE_SIZE; i++) {
            #pragma unroll
            for (int j = 0; j < REG_TILE_SIZE; j++) {
                int out_row = row + i;
                int out_col = col + j;
                if (out_row < N && out_col < N) {
                    out[out_row * N + out_col] = sum[i][j];
                }
            }
        }
    }
}

